import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { updateAnalyze } from "../handlers/updateAnalyze";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";
import type { UpdateAnalyzeHtmlRequest } from "../types/UpdateAnalyzeHtmlRequest";

type Data = Awaited<ReturnType<typeof updateAnalyze>>;
type Vars = { spacePk: SpacePartition; req: UpdateAnalyzeHtmlRequest };

export function useUpdateAnalyze(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => updateAnalyze(vars.spacePk, vars.req),
    ...options,
  });
}
